const testCase = $input.first().json;
console.log(`\n========================================`);
console.log(`\u{1F9EA} [${testCase.order}/${$execution.customData.get('totalTests')}] ${testCase.id} - ${testCase.name}`);
console.log(`   Categoria: ${testCase.category}`);
console.log(`   Prioridad: ${testCase.priority}`);
console.log(`   Phone: ${testCase.phone}`);
console.log(`   Expected: ${testCase.expectedScenario}`);
console.log(`========================================`);
return [{ json: testCase }];

const phone = $('Pre-Test Log').first().json.phone;
console.log(`📞 Executing WeeklySchedulingPrompt with test_phone_filter = ${phone}`);
return [{ json: { test_phone_filter: phone } }];

const testCase = $('Pre-Test Log').first().json;
const dbResults = $input.all();
let allPassed = true;
let details = [];
let failedValidations = [];

testCase.validations.forEach((validation, idx) => {
  const result = dbResults[idx];
  let actualValue = 0;
  if (result && result.json) {
    actualValue = result.json.cnt !== undefined ? Number(result.json.cnt) : 0;
  }

  let passed = false;
  if (validation.operator === '=') {
    passed = actualValue === validation.expected;
  } else if (validation.operator === '>=') {
    passed = actualValue >= validation.expected;
  } else {
    passed = actualValue === validation.expected;
  }

  if (!passed) {
    allPassed = false;
    failedValidations.push(validation.id);
  }

  details.push({
    id: validation.id,
    description: validation.description,
    expected: validation.expected,
    actual: actualValue,
    operator: validation.operator || '=',
    passed
  });

  const emoji = passed ? '\u2705' : '\u274C';
  console.log(`   ${emoji} ${validation.id}: expected ${validation.operator || '='} ${validation.expected}, got ${actualValue} \u2014 ${validation.description}`);
});

const result = {
  order: testCase.order,
  testId: testCase.id,
  testName: testCase.name,
  category: testCase.category,
  priority: testCase.priority,
  expectedScenario: testCase.expectedScenario,
  passed: allPassed,
  output: `Validations: ${details.filter(d => d.passed).length}/${details.length} passed`,
  error: allPassed ? null : `Failed: ${failedValidations.join(', ')}`,
  executedAt: new Date().toISOString(),
  details
};

let allResults = [];
try {
  const existing = $execution.customData.get('testResults');
  if (existing) allResults = JSON.parse(existing);
} catch(e) {}
allResults.push(result);
$execution.customData.set('testResults', JSON.stringify(allResults));

console.log(`${allPassed ? '\u2705 PASSED' : '\u274C FAILED'}: [${testCase.order}] ${testCase.id} (${testCase.expectedScenario}) \u2014 ${details.filter(d => d.passed).length}/${details.length} validations`);

return [{ json: result }];

let results = [];
if (items && items.length > 0 && items[0].json && Array.isArray(items[0].json.results)) {
  results = items[0].json.results;
}
const total = results.length;
const passed = results.filter(r => r.passed);
const failed = results.filter(r => !r.passed);
const passRateRaw = total > 0 ? (passed.length / total) * 100 : 0;
const passRate = passRateRaw % 1 === 0 ? passRateRaw.toFixed(0) : passRateRaw.toFixed(1);

let statusEmoji = failed.length === 0 ? '\u2705' : '\u274C';
if (total === 0) statusEmoji = '\u26A0\uFE0F';

let mdReport = `*\u{1F4CA} Test Report \u2014 WeeklySchedulingPrompt*\n`;
mdReport += `\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n`;
mdReport += `*Status:* ${statusEmoji} ${failed.length === 0 ? 'ALL PASS' : 'HAS FAILURES'}\n`;
mdReport += `*Score:* ${passRate}% (${passed.length}/${total})\n`;
mdReport += `*Time:* ${new Date().toLocaleString('es-CO')}\n\n`;

mdReport += `*Scenarios Validated:*\n`;
results.forEach(r => {
  const icon = r.passed ? '\u2705' : '\u274C';
  mdReport += `${icon} *${r.testId}* [${r.expectedScenario}] \u2014 ${r.testName}\n`;
  if (r.details) {
    r.details.forEach(d => {
      const dIcon = d.passed ? '\u2714' : '\u2757';
      mdReport += `   ${dIcon} ${d.id}: ${d.description} (${d.actual}/${d.expected})\n`;
    });
  }
});

if (failed.length > 0) {
  mdReport += `\n*\u{1F6A8} Failures:*\n`;
  failed.forEach(f => {
    mdReport += `\u2022 *[${f.priority}] ${f.testName}*: ${f.error}\n`;
  });
}

console.log('\n\u2554' + '\u2550'.repeat(52) + '\u2557');
console.log(`\u2551 WeeklySchedulingPrompt Test Report`.padEnd(53) + '\u2551');
console.log('\u2560' + '\u2550'.repeat(52) + '\u2563');
console.log(`\u2551 STATUS: ${statusEmoji}  RATE: ${passRate}% (${passed.length}/${total})`.padEnd(53) + '\u2551');
console.log('\u2560' + '\u2550'.repeat(52) + '\u2563');
results.forEach(r => {
  const icon = r.passed ? '\u2705' : '\u274C';
  console.log(`\u2551 ${icon} ${r.testId} [${r.expectedScenario}]`.padEnd(53) + '\u2551');
});
console.log('\u255A' + '\u2550'.repeat(52) + '\u255D');

results.forEach(r => {
  const icon = r.passed ? '\u2705' : '\u274C';
  console.log(`\n${icon} ${r.testId} \u2014 ${r.testName}`);
  if (r.details) {
    r.details.forEach(d => {
      const dIcon = d.passed ? '  \u2714' : '  \u2757';
      console.log(`${dIcon} ${d.id}: expected ${d.operator} ${d.expected}, got ${d.actual}`);
    });
  }
});

return [{
  json: {
    meta: { timestamp: new Date().toISOString(), totalTests: total, success: failed.length === 0 },
    markdownReport: mdReport,
    stats: { passed: passed.length, failed: failed.length, rate: parseFloat(passRate) },
    failures: failed.map(r => ({ testId: r.testId, name: r.testName, category: r.category, error: r.error, details: r.details }))
  }
}];
